function reviewKnownThird(lessons,adapter){
    const lesson=lessons.find(l=>l.id==='detail-p-hearing-01');
    if(!lesson?.learning||lesson.contentKind!=='exercise'||lesson.learning.contentReview||instructionFingerprint(lesson)!=='f309d515')return 0;
    const l=lesson.learning;
    const position='Правая рука в позиции C4–G4: большой 1 у среднего до C4, средний 3 у E4. D4 между ними в исходной паре не звучит; левая рука отдыхает.';
    const listening='C4–E4 — движение вверх на большую терцию, затем возврат E4–C4 вниз; в четырёх нотах пары повторяются дважды. В образце слышны короткие просветы, а не слитное legato или аккорд.';
    lesson.description='Послушай известную пару C4–E4, представь и пропой её, затем сыграй правой 1–3–1–3. Сравни направление, расстояние и окончания звуков с образцом; это слуховое представление, не независимый тест распознавания.';
    l.goal=lesson.description;
    lesson.guide=adapter.normalizeGuide({...lesson.guide,setup:'Сядь устойчиво, плечи и запястье свободны; педаль не используется. '+position,motion:'После прослушивания спокойно сыграй C4–E4–C4–E4 пальцами 1–3–1–3. Отпускай каждый звук чуть раньше следующей доли, как в образце. Не удерживай обе клавиши и не поднимай свободные пальцы силой.',blind:'Сначала услышь и пропой знакомую пару, затем представь её без воспроизведения. Повтори исходные четыре ноты без подсказок после разбора. Это проверка памяти известной фразы, не распознавание неизвестного интервала.',mastery:'Три чистые MIDI-попытки исходной фразы, одна из памяти; ещё один повтор после перерыва, например завтра. Самостоятельно сравни пропетую и сыгранную линию. MIDI не оценивает пение, выбранные пальцы, тембр или независимое узнавание интервала.'});
    l.practiceSteps=[
      'Подготовка: '+position+' Послушай весь образец, затем пропой C–E–C–E в удобной голосу октаве. На пианино сохраняй регистр C4–E4. '+listening,
      'Медленный разбор: отдельно найди C4 и E4, сыграй вверх 1–3, остановись, затем вниз 3–1. Считай «раз, два, три, четыре»: новая атака на каждую долю. В исходном образце звук занимает 0,85 доли и заканчивается перед следующей атакой; последняя E4 тоже заканчивается через 0,85 доли. Затем собери четыре звука. Не добавляй D4 и не играй пару одновременно.',
      'Блок около 3–5 минут: короткое прослушивание, пение, игра и сравнение. После завершения попытки отдельно проверь перенос: E4–C4–D4–E4 пальцами 3–1–2–3. Сначала представь спуск через терцию и два соседних шага вверх. Это самостоятельная проба, а не фраза текущего зачёта; затем вернись к исходному уроку после перерыва.'
    ];
    l.selfCheck=[listening,'C–E — большая терция: четыре полутона; D4 пропущена только в исходной паре. Не сужай её до C–D и не заменяй E на E♭.','Если промежутки между звуками не слышны, проверь отпускания. Доля не сокращается из-за раннего окончания звука.','MIDI-челлендж подтверждает ноты и время известной фразы, но не независимое распознавание на слух. Подсказанные C4–E4 уже известны заранее: автоматического теста слуха здесь нет. Пение и совпадение внутреннего образа оцениваются самостоятельно.','Следующий шаг — сравнение с C4–E♭4 в следующем уроке после подготовки чёрной клавиши; это отдельная слуховая задача.'];
    l.rhythmNotice='Данные исходного упражнения сохранены: четыре атаки по доле, 56 BPM, каждый звук 0,85 доли, затем небольшой просвет. Это настройка standard проекта, не обозначение универсальной артикуляции и не legato.';
    l.coverageDomain='ear-transfer';l.nextLessonId='detail-p-hearing-02';
    l.references=[THEORY,INTERVALS,PRACTICE,FIVE_FINGERS,TECHNIQUE];
    l.referenceTitles={[THEORY]:'The Open University: большая терция C–E',[INTERVALS]:'The Open University: мелодические интервалы',[PRACTICE]:'Bob Duke и Amy Simmons: внутренний звуковой образ',[FIVE_FINGERS]:'Alfred: Musical Fingers, Book 1, с. 6',[TECHNIQUE]:'Diana Dumlavwalla: свободное запястье'};
    l.provenance={type:'project-technical-drill',author:'Упражнение проекта',purpose:'Связать заранее представленный и пропетый интервал C–E с заданной парой 1–3 правой руки и сравнить реальное звучание со своим намерением.',context:'Представление направления и расстояния перед игрой помогает осмысленно разбирать мелодию. Сначала работаем со знакомым материалом; распознавание неизвестного образца требует отдельного задания.',sourceNote:'Это существующая четырёхнотная заготовка проекта, не цитата из произведения. OpenLearn подтверждает название интервала; Duke и Simmons рекомендуют ясный звуковой образ и воспроизведение голосом. Пальцы, регистр, 56 BPM, длительность 0,85 и критерии MIDI выбраны проектом. Источники не утверждают этот урок и не подтверждают самостоятельный слуховой зачёт.'};
    l.sourceEvidenceIds=['ou-triads-2026-11-05','ou-melodic-intervals-2026-11-05','duke-simmons-small-goals-2026-11-05','alfred-musical-fingers-position-2026-11-05','dumlavwalla-basic-technique-2026-11-05'];
    l.contentReview={id:'known-third-imagery-v1',sourceFingerprint:'f309d515',reviewedFingerprint:instructionFingerprint(lesson)};
    return 1;
  }

