function upgradeKnownThirdPreparation(lessons){
    const lesson=lessons.find(l=>l.id==='detail-p-hearing-01'),previous=lesson?.learning?.contentReview;
    if(lesson?.contentKind!=='exercise'||previous?.id!=='known-third-imagery-v1'||previous.reviewedFingerprint!=='e49388c7'||instructionFingerprint(lesson)!=='e49388c7')return 0;
    const l=lesson.learning;
    l.after='detail-p-black-01';l.requires=['course05-03','course02-03','course04-01'];
    l.practiceSteps[0]=l.practiceSteps[0].replace('Подготовка: ','Подготовка: сначала пройди «Правая: секунды и терции», «Пять пальцев вверх» правой рукой и «Четверти: раз-и, два-и». ');
    l.contentReview={id:'known-third-imagery-v2',sourceFingerprint:'e49388c7',reviewedFingerprint:instructionFingerprint(lesson),previous:JSON.parse(JSON.stringify(previous))};
    return 1;

