function startPlayback(){
    if(state.started&&state.attemptMode!=='practice')state.attemptAssisted=true;
    if(!visibleStepCount()) return;
    ensureAudio();
    if(!state.playbackBpm) state.playbackBpm=lessonBpm(state.lesson);
    if(state.playbackIndex>=visibleStepCount()-1 && state.playbackVisualActive) state.playbackIndex=0;
    const range=practiceRange();if(state.playbackIndex<range.start||state.playbackIndex>=range.end)state.playbackIndex=range.start;
    state.playbackPlaying=true; state.playbackVisualActive=true; state.playbackNextAt=performance.now(); state.scoreFollowPending=state.scoreFollow;
    playbackTick();
  }
  function finishPlayback(){
    clearPlaybackRelease();
    if(state.playbackTimer){ clearTimeout(state.playbackTimer); state.playbackTimer=null; }
    state.playbackPlaying=false; state.playbackVisualActive=true; state.playbackNextAt=0; state.playbackActive=new Set();
    state.playbackIndex=Math.max(0,practiceRange().end-1); state.scoreFollowPending=state.scoreFollow;
    renderPlaybackOnly(); renderKeyboardOnly();
  }
